def mi_based_keff(mi_matrix_np, model_indices):
    """K_eff = (1/K) * sum_i [1 + sum_{j!=i} exp(-2 * MI_ij)]"""
    K = len(model_indices)
    if K <= 1:
        return 1.0
    keff = 0.0
    for i_idx in model_indices:
        term = 1.0
        for j_idx in model_indices:
            if i_idx != j_idx:
                term += np.exp(-2 * mi_matrix_np[i_idx, j_idx])
        keff += term
    return keff / K


def classify_panel(model_ids):
    """Classify panel by composition for scatter plot coloring."""
    n_api = sum(1 for m in model_ids if m in API_MODELS)
    if n_api == 3:
        return "all_api"
    elif n_api == 0:
        return "all_local"
    elif n_api == 2:
        return "2api_1local"
    else:
        return "1api_2local"


